#ifndef DIRECT_BOOT_LOGO_H
#define DIRECT_BOOT_LOGO_H
#include <stdint.h>
/* CSERGY boot logo (1 bit per pixel, MSB-left rows, stride=ceil(width/8)).
 * Generated by tests/generate_boot_logo.cjs from the brand PNG; part 0 is
 * "CSERGY", part 1 is "辰烁科技". x_offset is relative to the mark. */
typedef struct { uint16_t x_offset,y_offset; uint16_t width; uint16_t height; uint8_t stride; const uint8_t *data; } direct_boot_logo_part_t;
extern const direct_boot_logo_part_t direct_boot_logo_parts[2];
extern const uint16_t direct_boot_logo_width;
extern const uint16_t direct_boot_logo_height;
extern const char direct_boot_logo_marker[];
#endif
